public static int calculateTimeNeeded(int N) {
    if (N <= 4) {
        // For N = 4 the time is 2 minutes, for fewer people it would not make sense.
        // However, to keep the function safe, we return 0 for N < 4.
        return Math.max(0, 2 * N - 6);
    }
    return 2 * N - 6;
}

