public static int countDoubles(int[] numbers) {
    int count = 0;
    java.util.Set<Integer> set = new java.util.HashSet<>();
    for (int n : numbers) {
        set.add(n);
    }
    for (int n : numbers) {
        if ((n & 1) == 0) { // only even numbers can be twice another integer
            int half = n / 2;
            if (set.contains(half)) {
                count++;
            }
        }
    }
    return count;
}

