public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    if (start.length != n || end.length != n) {
        return "cannot be travelled";
    }
    // Helper to convert coordinate array to string key
    java.util.function.Function<int[], String> toKey = (int[] coord) -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };
    String startKey = toKey.apply(start);
    String endKey = toKey.apply(end);
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();

    for (int[] row : paths) {
        if (row == null || row.length != 2 * n) {
            continue; // invalid path, skip
        }
        int[] a = new int[n];
        int[] b = new int[n];
        System.arraycopy(row, 0, a, 0, n);
        System.arraycopy(row, n, b, 0, n);
        String keyA = toKey.apply(a);
        String keyB = toKey.apply(b);
        adj.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        adj.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
    }

    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors == null) {
            continue;
        }
        for (String nb : neighbors) {
            if (nb.equals(endKey)) {
                return "can be travelled";
            }
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.offer(nb);
            }
        }
    }

    return "cannot be travelled";
}

