public static String convertDatesToWeekdays(String date) {
    // Split the input string into month, day, and year components
    String[] parts = date.trim().split("\\s+");
    int month = Integer.parseInt(parts[0]);   // 1-12
    int day   = Integer.parseInt(parts[1]);   // 1-31
    int year  = Integer.parseInt(parts[2]);   // e.g., 1997

    // Map month number to month name
    String[] monthNames = {"January","February","March","April","May","June",
                           "July","August","September","October","November","December"};
    String monthName = monthNames[month - 1];

    // Determine the day of the week using Calendar
    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.setLenient(false);
    cal.set(year, month - 1, day); // Calendar month is 0-based
    int dayOfWeekIndex = cal.get(java.util.Calendar.DAY_OF_WEEK); // 1=Sunday, 7=Saturday

    // Map Calendar's day of week to weekday name
    String[] dayNames = {"Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"};
    String dayName = dayNames[dayOfWeekIndex - 1];

    // Build the formatted result string
    return monthName + " " + day + ", " + year + " is a " + dayName;
}

