public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) return false;
    int n = arr.length;
    if ((n & 1) == 1) return false; // odd length -> cannot pair all
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // normalize remainder to [0, k-1]
        freq[r]++;
    }
    // Check remainder 0
    if ((freq[0] & 1) == 1) return false;
    // If k even, middle remainder must also pair with itself
    if ((k & 1) == 0) {
        int mid = k / 2;
        if ((freq[mid] & 1) == 1) return false;
    }
    // For all other remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) continue; // already handled for even k case
        if (freq[r] != freq[complement]) return false;
    }
    return true;
}

