public String sortString(String s) {
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        map.merge(c, 1, Integer::sum);
    }
    java.lang.StringBuilder sb = new java.lang.StringBuilder();
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending pass
        Character last = null;
        while (true) {
            Character c;
            if (last == null) {
                c = map.firstKey();
            } else {
                c = map.higherKey(last);
            }
            if (c == null) break;
            sb.append(c);
            int cnt = map.get(c);
            if (cnt == 1) {
                map.remove(c);
            } else {
                map.put(c, cnt - 1);
            }
            remaining--;
            last = c;
        }
        if (remaining == 0) break;

        // Descending pass
        Character lastDesc = null;
        Character c = map.lastKey();
        sb.append(c);
        int cnt = map.get(c);
        if (cnt == 1) {
            map.remove(c);
        } else {
            map.put(c, cnt - 1);
        }
        remaining--;
        lastDesc = c;
        while (true) {
            Character d = map.lowerKey(lastDesc);
            if (d == null) break;
            sb.append(d);
            int cntd = map.get(d);
            if (cntd == 1) {
                map.remove(d);
            } else {
                map.put(d, cntd - 1);
            }
            remaining--;
            lastDesc = d;
        }
    }
    return sb.toString();
}

