public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    int n = s.length();
    if (n < k) return false;
    int total = 1 << k;          // number of possible binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1;        // keep only k bits
    int curr = 0;
    int count = 0;
    for (int i = 0; i < n; i++) {
        curr = ((curr << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[curr]) {
                seen[curr] = true;
                count++;
                if (count == total) return true; // all codes found
            }
        }
    }
    return false;
}

