public static int findSmallestInteger(int n) {
    if (n <= 0) return -1;
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;
    // Find the largest index i such that digits[i] < digits[i + 1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) i--;
    if (i < 0) return -1; // already the highest permutation
    // Find the largest index j > i such that digits[j] > digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) j--;
    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Reverse the suffix starting at i + 1
    int left = i + 1, right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    // Convert back to integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        // Result exceeds integer range
        return -1;
    }
}

