public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int s = 1; s * s <= i; s++) {
            int square = s * s;
            int value = dp[i - square] + 1;
            if (value < min) {
                min = value;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

